def _parse(v):
    """Parse a SemVer 2.0.0 string into (major, minor, patch, prerelease_list)."""
    s = v.strip()
    # Strip build metadata (everything from the first '+' onward).
    plus = s.find('+')
    if plus != -1:
        s = s[:plus]

    # Split off pre-release.
    dash = s.find('-')
    if dash != -1:
        core = s[:dash]
        pre = s[dash + 1:]
        prerelease = pre.split('.') if pre != '' else []
    else:
        core = s
        prerelease = []

    parts = core.split('.')
    major = int(parts[0]) if len(parts) > 0 and parts[0] != '' else 0
    minor = int(parts[1]) if len(parts) > 1 and parts[1] != '' else 0
    patch = int(parts[2]) if len(parts) > 2 and parts[2] != '' else 0
    return major, minor, patch, prerelease


def _is_numeric(ident):
    return ident.isdigit()


def _cmp_identifiers(a, b):
    """Compare two pre-release identifier lists per SemVer precedence."""
    for x, y in zip(a, b):
        xn = _is_numeric(x)
        yn = _is_numeric(y)
        if xn and yn:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif xn and not yn:
            # Numeric identifiers have lower precedence than alphanumeric.
            return -1
        elif not xn and yn:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    # All shared identifiers equal; shorter list has lower precedence.
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def _cmp_versions(a, b):
    ma, mia, pa, prea = _parse(a)
    mb, mib, pb, preb = _parse(b)

    if ma != mb:
        return -1 if ma < mb else 1
    if mia != mib:
        return -1 if mia < mib else 1
    if pa != pb:
        return -1 if pa < pb else 1

    # A version with a pre-release is lower than the same without one.
    if not prea and not preb:
        return 0
    if not prea:
        return 1
    if not preb:
        return -1

    return _cmp_identifiers(prea, preb)


def sort_versions(vs):
    """Return versions sorted by SemVer 2.0.0 precedence (lowest first), stable."""
    return sorted(vs, key=cmp_to_key(_cmp_versions))
